8: `timescale 1ns/1ps
9: 
10: // Array-level testbench: one GEMM tile through the N x N FlexPosit array.
11: //
12: //   out[i][j] = 2^scale[j] * sum_k act[i][k] * w[j][k]
13: //
14: // act[i][k]  FP8 E4M3 activation codes          build/act.mem    (i*K + k)
15: // w[j][k]    Posit(P, ES) weight codes, one     build/w.mem      ((j*K + k)*P + bit)
16: //            serialized bit per line, MSB first,
17: //            sign-magnitude (SerialPosit) order
18: // scale[j]   signed 5-bit per-column exponent   build/scale.mem  (j)
19: //
20: // Each FP16 output lane is printed as "LANE <i> <j> <hex>" for
21: // scripts/run_array_test.py to compare against model/flexposit_rtl_exact.py.
22: module array_tb;
23: 
24:     parameter integer N  = 4;
25:     parameter integer K  = 16;
26:     parameter integer P  = 4;
27:     parameter integer ES = 1;
28: 
29:     localparam integer ACT_WIDTH  = 8;
30:     localparam integer OUT_LANE_W = 16;
31:     localparam integer OUT_BUS_W  = N * OUT_LANE_W;
32: 
33:     reg clk, rst, active;
34:     reg [3:0] precision;
35:     reg [1:0] posit_es;
36:     reg signed [4:0] col_scale [N-1:0];
37: 
38:     wire done;
39:     wire compute_done;
40:     wire                 ship_valid;

361:                 (row_commit_count[rd_row] != {K_WIDTH{1'b0}}) &&
362:                 !row_done[rd_row];
363:         end
364:     endgenerate
365: 
366:     genvar rr, cc;
367:     generate
368:         for (rr = 0; rr < N; rr = rr + 1) begin : gen_active_row
369:             wire baseline_active_row =
370:                 (rr==0)? first_act_valid : active_shift_reg[N-rr];
371:             assign active_row[rr] = baseline_active_row | row_in_progress[rr];
372:         end
373:         for (cc = 0; cc < N; cc = cc + 1) begin : gen_active_column
374:             assign active_column[cc] = (cc == 0) ? active : fifo_col_re[cc-1];
375:         end
376:     endgenerate
377:     // Level signal; rises when every row's PE(N-1) has committed K
378:     // MACs. Includes the current-cycle pe_done pulse in the per-row K
379:     // test so the rising edge aligns with the same posedge the counter
380:     // would update. Independent of pipeline-drain condition: "compute
381:     // is done when every row has finished its K MACs" regardless of
382:     // whether weight-side `valid` has drained.
383:     wire [N-1:0] row_final_done;
384:     genvar rfd;
385:     generate
386:         for (rfd = 0; rfd < N; rfd = rfd + 1) begin : gen_row_final_done
387:             assign row_final_done[rfd] =
388:                 ((row_final_commit_count[rfd] +
389:                   {{(K_WIDTH-1){1'b0}}, pe_done[rfd*N + (N-1)]}) >= k_reg_in) &&
390:                 (k_reg_in != {K_WIDTH{1'b0}});
391:         end
392:     endgenerate
393:     assign all_rows_done = &row_final_done;
394: 
395:     // compute_done as a rising-edge pulse of all_rows_done. all_rows_done
396:     // is a level that stays high from last-row-K-commit until the next
397:     // tile's start_pulse resets the counters — leaving it as-is would
398:     // re-trigger ship-out every cycle SH_IDLE re-enters, until start_pulse.
399:     // The pulse form matches the legacy compute_done semantics that the
400:     // ship-out FSM (and controller S_WAIT_COMPUTE) were written against.
401:     reg all_rows_done_prev;
402:     always @(posedge clk or negedge rst) begin
403:         if (!rst)
404:             all_rows_done_prev <= 1'b0;
405:         else
406:             all_rows_done_prev <= all_rows_done;
407:     end
408:     wire compute_done = all_rows_done & ~all_rows_done_prev;
409:     assign compute_done_out = compute_done;
410: 
411:     // ------------------------------------------------------------------
412:     // Ship-out FSM + drain pipeline
413:     //   SH_IDLE       : waiting for compute_done
414:     //   SH_SHIP       : hand rows to the stage register (one per accepted cycle)
415:     //   SH_DONE       : wait for stage to drain, then pulse `done` and return
416:     //
417:     // FSM drives internal (emit_valid, emit_row) which select acc_{sign,exp,
418:     // man}_arr[emit_row][*]. Each column is normalized+rescaled combinationally
419:     // and captured into a one-entry stage register. The FP16 conversion runs
420:     // from the stage register (post-pipeline), so the critical path is split
421:     // into (mux -> normalize -> rescale) and (fp16 convert -> port). Adds one
422:     // cycle of drain fill latency; steady-state throughput is unchanged.
423:     // ------------------------------------------------------------------
424:     localparam integer LGN_SAFE = (N > 1) ? $clog2(N) : 1;
425:     localparam [1:0] SH_IDLE = 2'd0, SH_SHIP = 2'd1, SH_DONE = 2'd2;
426:     reg [1:0]          sh_state;
427:     reg                done_r;
428:     reg                compute_done_seen;
429:     reg                emit_valid;
430:     reg [LGN_SAFE-1:0] emit_row;
431:     assign             done = done_r;
432: 
433:     // Stage register (between rescale and FP16 convert). One-entry with a
434:     // valid/ready handshake; accepts new data whenever empty or the current
435:     // entry was accepted by the consumer.
436:     reg                 drain_stage_valid;
437:     reg [LGN_SAFE-1:0]  drain_stage_row;
438:     reg                 drain_stage_sign [0:N-1];
439:     reg [NORM_EXPW-1:0] drain_stage_exp  [0:N-1];
440:     reg [NORM_MANW-1:0] drain_stage_man  [0:N-1];
441: 
442:     wire drain_stage_ready = !drain_stage_valid || out_ready;
443: 
444:     // Combinational drain (per-column) at module scope so the stage register
445:     // can capture all N tuples together.
446:     wire                 drain_scaled_sign [0:N-1];
447:     wire [NORM_EXPW-1:0] drain_scaled_exp  [0:N-1];
448:     wire [NORM_MANW-1:0] drain_scaled_man  [0:N-1];
449: 
450:     always @(posedge clk or negedge rst) begin
451:         if (!rst) begin
452:             sh_state          <= SH_IDLE;
453:             emit_valid        <= 1'b0;
454:             emit_row          <= {LGN_SAFE{1'b0}};
455:             done_r            <= 1'b0;
456:             compute_done_seen <= 1'b0;
457:         end else begin
458:             done_r     <= 1'b0;
459:             emit_valid <= 1'b0;
460:             case (sh_state)
461:                 SH_IDLE: begin
462:                     if (compute_done) compute_done_seen <= 1'b1;
463:                     if (compute_done | compute_done_seen) begin
464:                         sh_state          <= SH_SHIP;
465:                         emit_row          <= {LGN_SAFE{1'b0}};
466:                         emit_valid        <= 1'b1;
467:                         compute_done_seen <= 1'b0;
468:                     end
469:                 end
470:                 SH_SHIP: begin
471:                     emit_valid <= 1'b1;
472:                     if (drain_stage_ready) begin
473:                         if (emit_row == (N-1)) begin
474:                             emit_valid <= 1'b0;
475:                             sh_state   <= SH_DONE;
476:                         end else begin
477:                             emit_row <= emit_row + 1'b1;
478:                         end
479:                     end
480:                 end

481:                 SH_DONE: begin
482:                     emit_valid <= 1'b0;
483:                     if (!drain_stage_valid) begin
484:                         done_r   <= 1'b1;
485:                         sh_state <= SH_IDLE;
486:                     end
487:                 end
488:                 default: sh_state <= SH_IDLE;
489:             endcase
490:         end
491:     end
492: 
493:     integer drc;
494:     always @(posedge clk or negedge rst) begin
495:         if (!rst) begin
496:             drain_stage_valid <= 1'b0;
497:             drain_stage_row   <= {LGN_SAFE{1'b0}};
498:             for (drc = 0; drc < N; drc = drc + 1) begin
499:                 drain_stage_sign[drc] <= 1'b0;
500:                 drain_stage_exp[drc]  <= {NORM_EXPW{1'b0}};
501:                 drain_stage_man[drc]  <= {NORM_MANW{1'b0}};
502:             end
503:         end else if (drain_stage_ready) begin
504:             drain_stage_valid <= emit_valid;
505:             drain_stage_row   <= emit_row;
506:             for (drc = 0; drc < N; drc = drc + 1) begin
507:                 drain_stage_sign[drc] <= drain_scaled_sign[drc];
508:                 drain_stage_exp[drc]  <= drain_scaled_exp[drc];
509:                 drain_stage_man[drc]  <= drain_scaled_man[drc];
510:             end
511:         end
512:     end
513: 
514:     // Module outputs driven by the pipeline stage.
515:     assign out_valid = drain_stage_valid;
516:     assign out_row   = drain_stage_row;
517: 
518:     // Row mux + per-column normalize/rescale (feeds the stage register).
519:     // FP16 convert runs from the stage register (post-pipeline).
520:     // Rescale is a signed exponent adjustment, so it adds no multiplier.
521:     genvar cn;
522:     generate
523:         for (cn = 0; cn < N; cn = cn + 1) begin : gen_ship_col
524:             wire                       sel_sign;
525:             wire [ACC_EXPW-1:0]        sel_exp;
526:             wire [ACC_MANW+GRS-1:0]    sel_man;
527:             assign sel_sign = acc_sign_arr[emit_row][cn];
528:             assign sel_exp  = acc_exp_arr [emit_row][cn];
529:             assign sel_man  = acc_man_arr [emit_row][cn];
530: 
531:             wire                  norm_sign;
532:             wire [NORM_EXPW-1:0]  norm_exp;
533:             wire [NORM_MANW-1:0]  norm_man;
534:             bfp_normalize #(
535:                 .ACC_EXPW (ACC_EXPW),
536:                 .ACC_MANW (ACC_MANW),
537:                 .GRS      (GRS),
538:                 .NORM_EXPW(NORM_EXPW)
539:             ) u_norm (
540:                 .in_sign (sel_sign),
541:                 .in_exp  (sel_exp),
542:                 .in_man  (sel_man),
543:                 .out_sign(norm_sign),
544:                 .out_exp (norm_exp),
545:                 .out_man (norm_man)
546:             );
547: 
548:             wire                  scaled_sign;
549:             wire [NORM_EXPW-1:0]  scaled_exp;
550:             wire [NORM_MANW-1:0]  scaled_man;
551:             bfp_pow2_rescale #(
552:                 .EXP_WIDTH  (NORM_EXPW),
553:                 .MAN_WIDTH  (NORM_MANW),
554:                 .SCALE_WIDTH(SCALE_WIDTH)
555:             ) u_rescale (
556:                 .in_sign (norm_sign),
557:                 .in_exp  (norm_exp),
558:                 .in_man  (norm_man),
559:                 .scale   (col_scale_reg[cn]),
560:                 .out_sign(scaled_sign),
561:                 .out_exp (scaled_exp),
562:                 .out_man (scaled_man)
563:             );
564: 
565:             // Expose scaled_* per column so the stage register can capture
566:             // all N tuples together.
567:             assign drain_scaled_sign[cn] = scaled_sign;
568:             assign drain_scaled_exp[cn]  = scaled_exp;
569:             assign drain_scaled_man[cn]  = scaled_man;
570: 
571:             // Convert to IEEE 754 binary16 from the pipelined stage.
572:             wire [15:0] fp16_lane;
573:             bfp_to_fp16 #(
574:                 .IN_EXPW   (NORM_EXPW),
575:                 .IN_MANW   (NORM_MANW),
576:                 .BIAS_DELTA(FP16_BIAS_DELTA)
577:             ) u_to_fp16 (
578:                 .in_sign(drain_stage_sign[cn]),
579:                 .in_exp (drain_stage_exp[cn]),
580:                 .in_man (drain_stage_man[cn]),
581:                 .fp16   (fp16_lane)
582:             );
583: 
584:             assign out_data[cn*OUT_LANE_W +: OUT_LANE_W] = fp16_lane;
585:         end
586:     endgenerate
587: 
588: endmodule
589: 
